#![cfg(all(windows,feature="producer-test-fixture"))]
use std::{io::{BufRead,BufReader,Read,Write},os::windows::process::CommandExt,path::{Path,PathBuf},process::{Child,Command,Stdio},sync::mpsc,time::{Duration,Instant}};
use serde_json::{json,Value};

struct Owned(Child);
impl Drop for Owned {fn drop(&mut self){if self.0.try_wait().ok().flatten().is_none(){let _=self.0.kill();let _=self.0.wait();}}}
fn fixture()->(PathBuf,PathBuf) {let mut b=[0u8;16];getrandom::fill(&mut b).unwrap();let id:String=b.iter().map(|v|format!("{v:02x}")).collect();let base=Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("MindTrailProducerRecovery-{id}"));std::fs::create_dir(&base).unwrap();std::fs::create_dir(base.join("barrier")).unwrap();(base.join("state"),base)}
fn event(session:&str)->Value {json!({"v":1,"session":session,"seq":1,"ts":"2024-01-01T00:00:00Z","type":"task.start","payload":{"title":"T","goal":"G","project":"P"}})}
fn send(child:&mut Child,value:&Value) {let input=child.stdin.as_mut().unwrap();serde_json::to_writer(&mut *input,value).unwrap();input.write_all(b"\n").unwrap();input.flush().unwrap();}
fn start(root:&Path,mcp:bool,stage:Option<&str>,session:&str)->(Owned,mpsc::Receiver<Value>) {
    let mut command=Command::new(env!("CARGO_BIN_EXE_mindtrail-producer"));if mcp {command.args(["mcp","--queue","sample"]);}else{command.args(["submit-events","--queue","sample","--batch-id","batch"]);}
    command.env("MINDTRAIL_TEST_ROOT",root).creation_flags(0x08000000).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null());if let Some(stage)=stage {command.env("MINDTRAIL_TEST_BARRIER_STAGE",stage);}
    let mut child=command.spawn().unwrap();let stdout=child.stdout.take().unwrap();let (tx,rx)=mpsc::channel::<Value>();std::thread::spawn(move || {for line in BufReader::new(stdout).lines().map_while(Result::ok) {if let Ok(value)=serde_json::from_str(&line){if tx.send(value).is_err(){break}}}});
    if mcp {send(&mut child,&json!({"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-11-25","capabilities":{},"clientInfo":{"name":"recovery","version":"1"}}}));assert_eq!(rx.recv_timeout(Duration::from_secs(8)).unwrap()["result"]["protocolVersion"],"2025-11-25");send(&mut child,&json!({"jsonrpc":"2.0","method":"notifications/initialized"}));send(&mut child,&json!({"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"trace_task_start","arguments":{"session":session,"operation_id":"op","title":"T","goal":"G","project":"P"}}}));}
    else {child.stdin.take().unwrap().write_all(&serde_json::to_vec(&vec![event(session)]).unwrap()).unwrap();}
    (Owned(child),rx)
}
fn wait_barrier(child:&mut Child,base:&Path,stage:&str) {let deadline=Instant::now()+Duration::from_secs(15);loop {if let Ok(value)=std::fs::read_to_string(base.join("barrier/ready")){assert_eq!(value,stage);return}assert!(child.try_wait().unwrap().is_none(),"child exited before {stage}");assert!(Instant::now()<deadline,"barrier timed out: {stage}");std::thread::sleep(Duration::from_millis(10));}}
fn read_page(root:&Path,session:&str,since:u64)->Option<Value> {let endpoint:Value=serde_json::from_slice(&std::fs::read(root.join("endpoint.json")).unwrap()).unwrap();let port=endpoint["port"].as_u64().unwrap() as u16;let token=endpoint["token"].as_str().unwrap();let mut stream=std::net::TcpStream::connect(("127.0.0.1",port)).unwrap();stream.set_read_timeout(Some(Duration::from_secs(3))).unwrap();write!(stream,"GET /v1/sessions/{session}/events?since_seq={since}&limit=1 HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nAuthorization: Bearer {token}\r\nConnection: close\r\n\r\n").unwrap();let mut bytes=String::new();stream.read_to_string(&mut bytes).unwrap();let (head,body)=bytes.split_once("\r\n\r\n").unwrap();if head.starts_with("HTTP/1.1 404"){return None}assert!(head.starts_with("HTTP/1.1 200"));Some(serde_json::from_str(body).unwrap())}
fn read_events(root:&Path,session:&str)->Option<Value> {read_page(root,session,0)}
fn all_events(root:&Path,session:&str)->Vec<Value> {let mut since=0;let mut events=Vec::new();loop {let page=read_page(root,session,since).unwrap();let items=page["events"].as_array().unwrap();if items.is_empty(){break}for item in items {let seq=item["seq"].as_u64().unwrap();assert_eq!(seq,since+1);since=seq;events.push(item.clone());}}events}
fn expected_event(session:&str,mcp:bool,bytes:&[u8])->Value {let request:Value=serde_json::from_slice(bytes).unwrap();let mut expected=event(session);if mcp {assert_eq!(request[0]["operation_id"],"op");expected["ts"]=request[0]["ts"].clone();}expected}
fn explicit_child(root:&Path,batch:&str,items:&[Value],stage:Option<&str>)->(Owned,mpsc::Receiver<Value>) {let mut command=Command::new(env!("CARGO_BIN_EXE_mindtrail-producer"));command.args(["submit-events","--queue","sample","--batch-id",batch]).env("MINDTRAIL_TEST_ROOT",root).creation_flags(0x08000000).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null());if let Some(stage)=stage{command.env("MINDTRAIL_TEST_BARRIER_STAGE",stage);}let mut child=command.spawn().unwrap();child.stdin.take().unwrap().write_all(&serde_json::to_vec(items).unwrap()).unwrap();let stdout=child.stdout.take().unwrap();let (tx,rx)=mpsc::channel::<Value>();std::thread::spawn(move || {for line in BufReader::new(stdout).lines().map_while(Result::ok){if let Ok(value)=serde_json::from_str(&line){let _=tx.send(value);}}});(Owned(child),rx)}
fn explicit_result(root:&Path,batch:&str,items:&[Value])->Value {let (mut child,rx)=explicit_child(root,batch,items,None);let value=rx.recv_timeout(Duration::from_secs(10)).unwrap();let _=child.0.wait().unwrap();value}
fn queue_row(root:&Path,mcp:bool)->Option<(Vec<u8>,String,Option<String>)> {use rusqlite::OptionalExtension;let mode=if mcp{"mcp"}else{"explicit"};let db=rusqlite::Connection::open_with_flags(root.join(format!("producers/{mode}/sample/queue.sqlite3")),rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY).unwrap();db.query_row("SELECT request,status,outcome FROM entries",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).optional().unwrap()}
fn hold_committed_response(root:&Path,hold:bool)->(Vec<u8>,mpsc::Receiver<(Vec<u8>,Value)>,mpsc::Sender<()>,std::thread::JoinHandle<()>) {
    let original=std::fs::read(root.join("endpoint.json")).unwrap();let mut endpoint:Value=serde_json::from_slice(&original).unwrap();let real=endpoint["port"].as_u64().unwrap() as u16;let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();endpoint["port"]=json!(listener.local_addr().unwrap().port());std::fs::write(root.join("endpoint.json"),serde_json::to_vec(&endpoint).unwrap()).unwrap();let (ready,observed)=mpsc::channel();let (release,wait)=mpsc::channel();
    let thread=std::thread::spawn(move || {for index in 0..2 {let (mut input,_)=listener.accept().unwrap();input.set_read_timeout(Some(Duration::from_secs(5))).unwrap();let mut headers=Vec::new();let mut byte=[0];while !headers.ends_with(b"\r\n\r\n"){input.read_exact(&mut byte).unwrap();headers.push(byte[0]);}let text=String::from_utf8(headers).unwrap();let length=text.lines().find_map(|s|s.to_ascii_lowercase().strip_prefix("content-length: ").and_then(|n|n.parse::<usize>().ok())).unwrap_or(0);let mut body=vec![0;length];input.read_exact(&mut body).unwrap();let mut forward=std::net::TcpStream::connect(("127.0.0.1",real)).unwrap();forward.set_read_timeout(Some(Duration::from_secs(5))).unwrap();for line in text.lines().filter(|s|!s.is_empty()){if line.to_ascii_lowercase().starts_with("host:"){write!(forward,"host: 127.0.0.1:{real}\r\n").unwrap()}else{write!(forward,"{line}\r\n").unwrap()}}write!(forward,"Connection: close\r\n\r\n").unwrap();forward.write_all(&body).unwrap();let mut response=Vec::new();forward.read_to_end(&mut response).unwrap();assert!(response.starts_with(b"HTTP/1.1 200"));if index==0 {input.write_all(&response).unwrap();}else {let offset=response.windows(4).position(|b|b==b"\r\n\r\n").unwrap()+4;let receipt=serde_json::from_slice(&response[offset..]).unwrap();if !hold {input.write_all(&response).unwrap();}ready.send((body,receipt)).unwrap();if hold {let _=wait.recv_timeout(Duration::from_secs(15));}}}});(original,observed,release,thread)
}
#[test] fn process_kill_at_local_and_receipt_barriers() {
    for mcp in [false,true] {for stage in ["before_local_commit","after_local_commit","before_post","before_receipt_commit","after_receipt_commit"] {
        let (root,base)=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let session=format!("s-{}-{stage}",if mcp{"m"}else{"e"});let (mut child,_rx)=start(&root,mcp,Some(stage),&session);wait_barrier(&mut child.0,&base,stage);child.0.kill().unwrap();child.0.wait().unwrap();drop(child);
        let before=queue_row(&root,mcp);if stage=="before_local_commit" {assert!(before.is_none())}else{assert!(before.is_some());assert_eq!(before.as_ref().unwrap().1,if stage=="after_receipt_commit"{"committed"}else{"pending"});}
        let prior=read_events(&root,&session);if matches!(stage,"before_receipt_commit"|"after_receipt_commit") {assert_eq!(prior.as_ref().unwrap()["events"].as_array().unwrap().len(),1)}else{assert!(prior.is_none())}
        let trap=if stage=="after_receipt_commit" {let original=std::fs::read(root.join("endpoint.json")).unwrap();let mut value:Value=serde_json::from_slice(&original).unwrap();let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();value["port"]=json!(listener.local_addr().unwrap().port());std::fs::write(root.join("endpoint.json"),serde_json::to_vec(&value).unwrap()).unwrap();Some((listener,original))}else{None};
        let capture=if trap.is_none(){Some(hold_committed_response(&root,false))}else{None};let (mut retry,rx)=start(&root,mcp,None,&session);let response=rx.recv_timeout(Duration::from_secs(10)).unwrap();if mcp {assert_eq!(response["result"]["structuredContent"]["status"],"committed");assert_eq!(response["result"]["structuredContent"]["seq"],1);retry.0.stdin.take();}else{assert_eq!(response["status"],"committed");let receipt=&response["receipt"];assert_eq!(receipt["accepted"],if stage=="before_receipt_commit"{0}else{1});assert_eq!(receipt["duplicates"],if stage=="before_receipt_commit"{1}else{0});}
        let status=retry.0.wait().unwrap();assert!(status.success());let sent=if let Some((original,observed,_release,proxy))=capture {let (sent,_)=observed.recv_timeout(Duration::from_secs(5)).unwrap();proxy.join().unwrap();std::fs::write(root.join("endpoint.json"),original).unwrap();Some(sent)}else{None};if let Some((listener,original))=trap {assert_eq!(listener.accept().unwrap_err().kind(),std::io::ErrorKind::WouldBlock);std::fs::write(root.join("endpoint.json"),original).unwrap();}let after=queue_row(&root,mcp).unwrap();assert_eq!(after.1,"committed");if let Some((bytes,_,_))=before {assert_eq!(after.0,bytes);}if let Some(sent)=sent {assert_eq!(sent,after.0);}assert_eq!(all_events(&root,&session),vec![expected_event(&session,mcp,&after.0)]);gateway.shutdown().unwrap();eprintln!("isolated recovery fixture: {}",base.display());
    }}
}
#[test] fn kill_after_gateway_commit_before_response_for_both_modes() {
    for mcp in [false,true] {let (root,base)=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let session=if mcp{"m-lost"}else{"e-lost"};let (original,observed,release,proxy)=hold_committed_response(&root,true);let (mut child,_rx)=start(&root,mcp,None,session);
        let (sent,receipt)=observed.recv_timeout(Duration::from_secs(10)).unwrap();assert_eq!(receipt["accepted"],1);assert_eq!(receipt["duplicates"],0);child.0.kill().unwrap();child.0.wait().unwrap();drop(child);release.send(()).unwrap();proxy.join().unwrap();std::fs::write(root.join("endpoint.json"),original).unwrap();
        let before=queue_row(&root,mcp).unwrap();assert_eq!(before.1,"pending");assert_eq!(before.0,sent);assert_eq!(all_events(&root,session),vec![expected_event(session,mcp,&sent)]);
        let (original,observed,_release,proxy)=hold_committed_response(&root,false);let (mut retry,rx)=start(&root,mcp,None,session);let response=rx.recv_timeout(Duration::from_secs(10)).unwrap();if mcp {assert_eq!(response["result"]["structuredContent"]["seq"],1);retry.0.stdin.take();}else{assert_eq!(response["receipt"]["duplicates"],1);}assert!(retry.0.wait().unwrap().success());let (resent,duplicate)=observed.recv_timeout(Duration::from_secs(5)).unwrap();proxy.join().unwrap();std::fs::write(root.join("endpoint.json"),original).unwrap();assert_eq!(resent,sent);assert_eq!(duplicate["duplicates"],1);let after=queue_row(&root,mcp).unwrap();assert_eq!(before.0,after.0);let outcome:Value=serde_json::from_str(after.2.as_deref().unwrap()).unwrap();assert_eq!(outcome["duplicates"],1);assert_eq!(all_events(&root,session),vec![expected_event(session,mcp,&sent)]);gateway.shutdown().unwrap();eprintln!("isolated lost-response fixture: {}",base.display());
    }
}
#[test] fn kill_after_repair_commit_before_original_batch() {
    let (root,base)=fixture();let gateway=mindtrail_lib::gateway::lifecycle::Gateway::start(&root).unwrap();let session="repair-recovery";let first=event(session);let second=json!({"v":1,"session":session,"seq":2,"ts":"2024-01-01T00:00:00Z","type":"capability.intent","payload":{"id":"c","title":"C"}});let third=json!({"v":1,"session":session,"seq":3,"ts":"2024-01-01T00:00:00Z","type":"task.done","payload":{}});
    assert_eq!(explicit_result(&root,"one",&[first.clone()])["status"],"committed");assert_eq!(explicit_result(&root,"three",&[third.clone()])["error"]["code"],"seq_gap");
    let (mut child,_rx)=explicit_child(&root,"two",&[second.clone()],Some("after_repair_commit"));wait_barrier(&mut child.0,&base,"after_repair_commit");child.0.kill().unwrap();child.0.wait().unwrap();drop(child);
    let db=rusqlite::Connection::open_with_flags(root.join("producers/explicit/sample/queue.sqlite3"),rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY).unwrap();let (repair,status):(Vec<u8>,String)=db.query_row("SELECT request,status FROM repairs",[],|r|Ok((r.get(0)?,r.get(1)?))).unwrap();assert_eq!(status,"committed");let original:String=db.query_row("SELECT status FROM entries WHERE batch_id='three'",[],|r|r.get(0)).unwrap();assert_eq!(original,"pending");drop(db);assert_eq!(all_events(&root,session),vec![first.clone(),second.clone()]);
    let result=explicit_result(&root,"three",&[third.clone()]);assert_eq!(result["status"],"committed");assert_eq!(result["receipt"],json!({"accepted":1,"duplicates":0,"last_seq":3}));let missing=explicit_result(&root,"two",&[second.clone()]);assert_eq!(missing["receipt"]["duplicates"],1);
    let db=rusqlite::Connection::open_with_flags(root.join("producers/explicit/sample/queue.sqlite3"),rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY).unwrap();let after:Vec<u8>=db.query_row("SELECT request FROM repairs",[],|r|r.get(0)).unwrap();assert_eq!(after,repair);drop(db);assert_eq!(all_events(&root,session),vec![first,second,third]);gateway.shutdown().unwrap();eprintln!("isolated repair recovery fixture: {}",base.display());
}
